import { BASE_PATH } from '@/lib/site'

/**
 * The graticule globe, generated by scripts/make-map.mjs into
 * public/globe.svg. Decorative, so the alt text is empty; the caption beside
 * it says what it is. Size attributes match the file so nothing shifts.
 */
export function Globe({ className }: { className?: string }) {
  return (
    // eslint-disable-next-line @next/next/no-img-element
    <img className={className} src={`${BASE_PATH}/globe.svg`} width={644} height={644} alt="" decoding="async" />
  )
}
